import fitz, re
path='assets/uploads/647b5227_reaction-pathway-tuning-between-electron-transfer-mediated-degradation-and-polymerization-in-fe-mos2-based-persulfate.pdf'
doc=fitz.open(path)
for i in range(doc.page_count):
    text=doc.load_page(i).get_text('text')
    if 'PMSO' in text or 'Fe(IV)' in text or 'quench' in text or 'Raman' in text:
        print('\n===== PAGE', i+1, '=====')
        lines=text.splitlines()
        for idx,line in enumerate(lines):
            if any(k in line for k in ['PMSO','Fe(IV)','quench','Raman']):
                print('\n'.join(lines[max(0,idx-2):min(len(lines),idx+4)]))
                print('---')
